import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

from collections import deque
def f(inp):
    h,w=len(inp),len(inp[0])
    # background = most common color
    from collections import Counter
    c=Counter(x for r in inp for x in r)
    bg=c.most_common(1)[0][0]
    out=[row[:] for row in inp]
    # flood from border through bg cells
    vis=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if inp[i][j]==bg: q.append((i,j)); vis[i][j]=True
    for j in range(w):
        for i in (0,h-1):
            if inp[i][j]==bg: q.append((i,j)); vis[i][j]=True
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and not vis[ni][nj] and inp[ni][nj]==bg:
                vis[ni][nj]=True;q.append((ni,nj))
    for i in range(h):
        for j in range(w):
            if inp[i][j]==bg and not vis[i][j]:
                out[i][j]=4
    return out
o=f(G['Demo pair 1 input'])
print(o==G['Demo pair 1 output'])
